<tr data-currency-rate>
    <td><input type="hidden" name="rates[<?= accountingEscape($rateKey) ?>][id]" value="<?= (int)($rateRow['id']??0) ?>"><input type="date" name="rates[<?= accountingEscape($rateKey) ?>][rate_date]" value="<?= accountingEscape(is_string($rateRow['rate_date']??null)?$rateRow['rate_date']:'') ?>" aria-label="Fecha de la tasa" data-rate-date></td>
    <td><select name="rates[<?= accountingEscape($rateKey) ?>][base_currency_id]" aria-label="Moneda base de la tasa"><?php foreach ($page['currencies'] as $baseCurrency): ?><?php if ((int)($record['id']??0)===(int)$baseCurrency['id']) continue; ?><option value="<?= (int)$baseCurrency['id'] ?>" <?= isset($rateRow['base_currency_id'])?((int)currencyCatalogId($rateRow['base_currency_id'])===(int)$baseCurrency['id']?'selected':''):($baseCurrency['code']===$page['settings']['primary_code']?'selected':'') ?>><?= accountingEscape($baseCurrency['code']) ?></option><?php endforeach; ?></select></td>
    <td><input name="rates[<?= accountingEscape($rateKey) ?>][rate]" inputmode="decimal" maxlength="21" value="<?= accountingEscape(is_string($rateRow['rate']??null)?$rateRow['rate']:'') ?>" aria-label="Tasa" data-rate-value></td>
    <td><input readonly value="<?= is_string($rateRow['rate']??null) && preg_match('/^[0-9]{1,12}(\.[0-9]{1,8})?$/',$rateRow['rate']) && bccomp($rateRow['rate'],'0',8)>0 ? accountingEscape(bcdiv('1',$rateRow['rate'],8)) : '' ?>" aria-label="Tasa inversa" data-rate-inverse></td>
    <td class="contact-row-action"><?php if (empty($rateRow['id'])): ?><button class="contact-button contact-icon-button" type="button" data-remove-currency-rate hidden aria-label="Quitar tasa nueva" title="Quitar tasa nueva"><?php require dirname(__DIR__).'/partials/remove-icon.php'; ?></button><?php endif; ?></td>
</tr>
